INSERT INTO
	SMUFP(
		  HOUSE_CODE
		, MENU_PROFILE_CODE
		, MENU_ID
		, ADD_USER_ID
		, ADD_DATE
		, ADD_TIME
	) VALUES (
		  ${HOUSE_CODE}
		, ${MENU_PROFILE_CODE}
		, ${MENU_ID}
		, ${session.ID}
		, ${current.DATE}
		, ${current.TIME}
	)


DELETE FROM SMUFP
WHERE HOUSE_CODE = ${HOUSE_CODE}
AND MENU_PROFILE_CODE = ${MENU_PROFILE_CODE}
